9) ctx.putImageData(imgData,0,0);
10) ctx.setTransform(1,0,0,1,0,0); // overlays drawn in device pixels
11) If wireframe: ctx.strokeStyle='rgba(235,240,250,0.9)'; ctx.lineWidth=1.25*dpr; ctx.beginPath(); for each EDGE pair (a,b): moveTo(sx[a],sy[a]),lineTo(sx[b],sy[b]); stroke(); plus tiny vertex dots: ctx.fillStyle='#dfe8f5', for each v fillRect(sx[v]-1.5*dpr,sy[v]-1.5*dpr,3*dpr,3*dpr).
